<?php
if(PHP_SAPI!=='cli')exit(1);ob_start();
require_once __DIR__.'/../koneksi.php';require_once __DIR__.'/http_form_scope.php';spp_test_assert_database_target($koneksi);
require_once __DIR__.'/../includes/legacy_full.php';require_once __DIR__.'/legacy_finance_support.php';
$base=rtrim(getenv('SPP_TEST_BASE_URL'),'/');spp_test_assert_http_clone($base,DB_NAME);$qa=dirname(getenv('SPP_TEST_ISOLATED_INSTANCE'));$audit=getenv('SPP_LATEST_AUDIT_ROOT');
$sources=json_decode(file_get_contents($audit.'/sources.json'),true);$jobs=json_decode(file_get_contents($qa.'/latest-source-jobs.json'),true);$actor=(int)lf_one($koneksi,"SELECT id FROM admin WHERE role='super_admin' AND is_active=1 LIMIT 1")['id'];$sessions=[];
$probe=$qa.'/upload-probe.bak';file_put_contents($probe,'Invalid SQL backup for access-control and retry tests.');
function latest_session(int $actor,int $unit,string $role='super_admin'): string {$sid='latest'.bin2hex(random_bytes(12));session_id($sid);session_start();$_SESSION=['admin_id'=>$actor,'admin_role'=>$role,'active_unit_id'=>$unit,'csrf_legacy_import'=>str_repeat('a',64)];session_write_close();return $sid;}
function latest_http(string $path,?string $sid=null,?array $post=null): array {global $base;$c=curl_init($base.'/'.$path);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_TIMEOUT=>180]);if($sid)curl_setopt($c,CURLOPT_COOKIE,'PHPSESSID='.$sid);if($post!==null){curl_setopt($c,CURLOPT_POST,true);curl_setopt($c,CURLOPT_POSTFIELDS,$post);} $body=curl_exec($c);if($body===false)throw new RuntimeException(curl_error($c));$status=curl_getinfo($c,CURLINFO_RESPONSE_CODE);curl_close($c);return [$status,$body];}
function latest_worker(): void {global $koneksi;$until=time()+900;do{$busy=(int)legacy_queue()->query("SELECT COUNT(*) FROM jobs WHERE state IN ('queued','processing','apply_queued','applying','simulate_queued','simulating')")->fetchColumn();$ready=legacy_readiness($koneksi)['ready'];if(!$busy&&$ready)return;usleep(250000);}while(time()<$until);throw new RuntimeException('Owned continuous QA worker did not complete');}
foreach([0,1,2,3] as $unit)$sessions[$unit]=latest_session($actor,$unit);
lft_assert(latest_http('legacy_import_api.php?action=health')[0]===403,'Anonymous accepted');
foreach(['admin','kasir','bendahara','inactive'] as $role){$username='latestqa'.bin2hex(random_bytes(7));$hash=password_hash(bin2hex(random_bytes(24)),PASSWORD_DEFAULT);lf_query($koneksi,"INSERT INTO admin(username,password,nama,role,unit_id,is_active) VALUES(?,?,'QA akses backup',?,1,?)",[$username,$hash,$role==='inactive'?'super_admin':$role,$role==='inactive'?0:1]);$testActor=(int)$koneksi->insert_id;try{lft_assert(latest_http('legacy_import_api.php?action=health',latest_session($testActor,1,$role==='inactive'?'super_admin':$role))[0]===403,'Other/inactive role accepted');}finally{lf_query($koneksi,'DELETE FROM admin WHERE id=?',[$testActor]);}}
foreach($sources as $s){$unit=$s['unit'];$sid=$sessions[$unit];
    foreach(['legacy_import.php?mode=students','legacy_import.php?mode=finance','legacy_full.php'] as $path){[$status,$html]=latest_http($path,$sid);lft_assert($status===200&&!str_contains($html,'accept=".dat"'),'Upload page restricted or broken');}
    latest_worker();$name=[1=>'SD.BaK',2=>'smp17102026',3=>'SMA.DAT'][$unit];$post=['action'=>'upload','category'=>'students','unit'=>(string)$unit,'csrf_token'=>str_repeat('a',64),'request_key'=>bin2hex(random_bytes(16)),'backup'=>new CURLFile($s['path'],'application/octet-stream',$name)];
    $accessPost=array_replace($post,['backup'=>new CURLFile($probe,'application/octet-stream','probe.bak')]);
    lft_assert(latest_http('legacy_import_api.php',$sid,array_replace($accessPost,['csrf_token'=>'wrong']))[0]===403,'CSRF accepted');
    lft_assert(latest_http('legacy_import_api.php',$sessions[0],$accessPost)[0]===409,'All Units upload accepted');
    [$status,$json]=latest_http('legacy_import_api.php',$sid,$post);$j=json_decode($json,true);lft_assert($status===200&&$j['name']===$name,'New upload rejected: '.$status.' '.$json);
    latest_worker();
    [$status,$json]=latest_http('legacy_import_api.php?action=status&id='.$j['id'],$sid);$result=json_decode($json,true);lft_assert($status===200&&$result['job']['state']==='ready'&&$result['job']['source_profile_version']==='2026','Live worker profile missing');
    lft_assert(latest_http('legacy_import_api.php',$sessions[$unit===1?2:1],['action'=>'confirm','id'=>$j['id'],'csrf_token'=>str_repeat('a',64),'confirmation'=>'IMPOR LEGACY'])[0]===403,'Cross-unit application accepted');
}
// Both misleading extensions and a real backup from the wrong unit fail before staging.
$bad=$qa.'/invalid-source.bak';file_put_contents($bad,'This is not a SQL Server backup.');
foreach([[$bad,'bad.bak',1],[$sources[0]['path'],'wrong-unit',2]] as [$path,$name,$unit]){latest_worker();$post=['action'=>'upload','category'=>'students','unit'=>(string)$unit,'csrf_token'=>str_repeat('a',64),'request_key'=>bin2hex(random_bytes(16)),'backup'=>new CURLFile($path,'application/octet-stream',$name)];[$status,$json]=latest_http('legacy_import_api.php',$sessions[$unit],$post);lft_assert($status===200,'Negative job was not examined');$j=json_decode($json,true);if($name==='bad.bak'){[$retryStatus,$retryJson]=latest_http('legacy_import_api.php',$sessions[$unit],$post);lft_assert($retryStatus===200&&json_decode($retryJson,true)['id']===$j['id'],'Duplicate upload job');}latest_worker();lft_assert(legacy_job($j['id'])['state']==='failed','Invalid/wrong-unit backup accepted');}
$browserJobs=[];foreach($jobs as $j)if($j['version']==='2026'&&$j['mode']==='full')$browserJobs[$j['unit']]=$j['id'];
[$status,$html]=latest_http('legacy_full.php?id='.$browserJobs[1].'&step=exceptions&section=savings',$sessions[1]);lft_assert($status===200&&str_contains($html,'id="additional-savings"'),'Additional source ledger guidance missing');
file_put_contents($qa.'/latest-browser.json',lf_json(['base'=>$base,'sessions'=>$sessions,'jobs'=>$browserJobs]));echo "PASS: actual extensionless/BAK/DAT uploads, retry, worker profile, native forms, anonymous/roles, CSRF, cross-unit, invalid source and wrong unit.\n";
